 const title=aside.querySelector('.aside-title');aside.replaceChildren();aside.append(title||Object.assign(document.createElement('div'),{className:'aside-title',textContent:'ในบทเรียนนี้'}));let list=document.createElement('div');list.className='cc-lesson-toc';aside.append(list);let links=items.map(({el,title},i)=>{let a=document.createElement('a');a.className='aside-row';a.href='#'+el.id;let n=document.createElement('span');n.textContent=String(i+1).padStart(2,'0');a.append(n,document.createTextNode(' '+title));list.append(a);a.addEventListener('click',e=>{e.preventDefault();el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});schedule()});return a});
 let active=-1,raf=0;function update(){raf=0;if(!aside.isConnected)return;let threshold=Math.min(105,window.innerHeight*.16),candidate=0;items.forEach(({els},i)=>{if(els.some(el=>el.isConnected&&el.getBoundingClientRect().top<=threshold))candidate=i});if(candidate===active)return;active=candidate;links.forEach((a,i)=>{a.classList.toggle('is-current',i===active);if(i===active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}function schedule(){if(!raf)raf=requestAnimationFrame(update)}scheduleToc=schedule;window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule,{passive:true});update();detachToc=()=>{window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);if(raf)cancelAnimationFrame(raf);scheduleToc=()=>{}};
