const selector='.cc-edit-code, #inlineCode, textarea[data-pilot-code], textarea[data-shared-code]';let input=null,results=[],selected=0,start=0,end=0,composing=false;let popup=document.createElement('div');popup.className='cc49-suggest cc-lesson-suggest';popup.hidden=true;let list=document.createElement('div'),hint=document.createElement('div');list.id='cc-lesson-suggest-list';list.setAttribute('role','listbox');hint.className='cc49-hint';popup.append(list,hint);document.body.append(popup);
function hide(){popup.hidden=true;results=[];if(input)input.removeAttribute('aria-activedescendant')}
function enabled(){try{return localStorage.getItem('codecraft-suggest-enabled')!=='0'}catch(_){return true}}
function validContext(s,l){let quote='',block=false,line=false;for(let i=0;i<s.length;i++){let ch=s[i],next=s[i+1];if(line){if(ch==='\n')line=false;continue}if(block){if(ch==='*'&&next==='/'){block=false;i++}continue}if(quote){if(ch==='\\'){i++;continue}if(quote.length===3&&s.slice(i,i+3)===quote){i+=2;quote=''}else if(quote.length===1&&ch===quote)quote='';continue}if(l==='python'&&ch==='#'){line=true;continue}if(l!=='python'&&ch==='/'&&next==='/'){line=true;i++;continue}if(l!=='python'&&ch==='/'&&next==='*'){block=true;i++;continue}if(ch==='"'||ch==="'"){if(l==='python'&&s.slice(i,i+3)===ch.repeat(3)){quote=ch.repeat(3);i+=2}else quote=ch}}return !quote&&!line&&!block}
function position(){if(popup.hidden||!input||!input.isConnected)return hide();let rect=input.getBoundingClientRect(),style=getComputedStyle(input),mirror=document.createElement('div');for(let k of ['fontFamily','fontSize','fontWeight','fontStyle','letterSpacing','lineHeight','paddingTop','paddingLeft','paddingRight','paddingBottom','borderTopWidth','borderLeftWidth','boxSizing','tabSize'])mirror.style[k]=style[k];Object.assign(mirror.style,{position:'fixed',visibility:'hidden',whiteSpace:'pre',top:rect.top+'px',left:rect.left+'px',width:rect.width+'px',overflow:'hidden',borderStyle:'solid'});mirror.textContent=input.value.slice(0,input.selectionStart);let mark=document.createElement('span');mark.textContent='\u200b';mirror.append(mark);document.body.append(mirror);let point=mark.getBoundingClientRect();mirror.remove();let x=point.left-input.scrollLeft,y=point.top-input.scrollTop,line=parseFloat(style.lineHeight)||20;if(y<rect.top-line||y>rect.bottom||x<rect.left||x>rect.right)return hide();let width=Math.min(360,innerWidth-16);popup.style.width=width+'px';popup.style.left=Math.max(8,Math.min(x,innerWidth-width-8))+'px';let height=popup.offsetHeight;popup.style.top=(y+line+height>innerHeight-8?Math.max(8,y-height):y+line)+'px'}
function draw(){list.replaceChildren();let l=lang();results.forEach((word,i)=>{let b=document.createElement('button'),w=document.createElement('span'),d=document.createElement('span');b.type='button';b.id='cc-lesson-word-'+i;b.className='cc49-option';b.setAttribute('role','option');b.setAttribute('aria-selected',String(i===selected));w.className='cc53-word';w.textContent=word;d.className='cc53-description';d.textContent=cc53Describe(l,word,ccLang==='en');b.append(w,d);b.addEventListener('pointerdown',e=>{e.preventDefault();insert(i)});list.append(b)});input.setAttribute('aria-activedescendant','cc-lesson-word-'+selected);hint.textContent=label('↑ ↓ เลือก · Enter / Tab แทรก · Esc ปิด','↑ ↓ select · Enter / Tab insert · Esc close');popup.hidden=false;let active=list.children[selected];if(active){let top=active.offsetTop,bottom=top+active.offsetHeight;if(top<list.scrollTop)list.scrollTop=top;else if(bottom>list.scrollTop+list.clientHeight)list.scrollTop=bottom-list.clientHeight}position()}
function update(){if(!input||!input.isConnected||!enabled()||composing||document.activeElement!==input||input.selectionStart!==input.selectionEnd)return hide();let pos=input.selectionStart,before=input.value.slice(0,pos),match=before.match(/[A-Za-z_][A-Za-z_0-9]*$/),l=lang();if(!match||match[0].length<2||!validContext(before.slice(0,-match[0].length),l))return hide();let prefix=match[0],suffix=(input.value.slice(pos).match(/^[A-Za-z_0-9]*/)||[''])[0];start=pos-prefix.length;end=pos+suffix.length;results=[...new Set(cc49Words[l]||[])].filter(w=>w.startsWith(prefix)&&w!==prefix+suffix).slice(0,6);if(!results.length)return hide();selected=0;draw()}
function insert(i){if(!results[i]||!input)return;input.setRangeText(results[i],start,end,'end');hide();input.dispatchEvent(new Event('input',{bubbles:true}));hide();input.focus()}
document.addEventListener('focusin',e=>{if(['lesson','cppunit'].includes(page)&&e.target.matches(selector)){input=e.target;input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-controls',list.id);update()}});document.addEventListener('focusout',e=>{if(e.target===input)hide()});document.addEventListener('input',e=>{if(e.target===input)update()});document.addEventListener('compositionstart',e=>{if(e.target===input){composing=true;hide()}});document.addEventListener('compositionend',e=>{if(e.target===input){composing=false;update()}});document.addEventListener('keydown',e=>{if(e.target!==input||popup.hidden||e.isComposing||composing||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();e.stopImmediatePropagation();selected=(selected+(e.key==='ArrowDown'?1:-1)+results.length)%results.length;draw()}else if(e.key==='Enter'||e.key==='Tab'){e.preventDefault();e.stopImmediatePropagation();insert(selected)}else if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();hide()}},true);document.addEventListener('click',e=>{if(e.target===input)update()});window.addEventListener('resize',position,{passive:true});document.addEventListener('scroll',position,true);
